const before=lessonHTML;lessonHTML=function(i){const m=lessons.get(i);return m?'<h2>'+m.title+'</h2>'+m.theory+m.practice+'<h3>Проверочный тест</h3><p>15 заданий: 10 с выбором и 5 открытых. В открытых заданиях вводи только запрошенное число; дробь можно записать через /. Полные преобразования запиши в тетради. После завершения доступны объяснения, процент и диаграмма тем.</p>':before(i);};
